// ESP-01S with stock AT firmware: send AT commands and print the replies.
#if defined(ESP32)
  #define ESP_SERIAL Serial2
#else
  #include <SoftwareSerial.h>
  SoftwareSerial espSerial({{TX}}, {{RX}});  // board RX, board TX
  #define ESP_SERIAL espSerial
#endif

void setup() {
  Serial.begin(115200);
#if defined(ESP32)
  ESP_SERIAL.begin(115200, SERIAL_8N1, {{TX}}, {{RX}});  // board RX, board TX
#else
  ESP_SERIAL.begin(9600);  // set the module to 9600 first: AT+UART_DEF=9600,8,1,0,0
#endif
  delay(1000);
  ESP_SERIAL.println("AT+GMR");
}

void loop() {
  while (ESP_SERIAL.available()) Serial.write(ESP_SERIAL.read());
  while (Serial.available()) ESP_SERIAL.write(Serial.read());
}
